INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13436, 1, 1, 'Children of the Gods', 'The System Lord Apophis launches an attack through the Stargate, tucked away by the military after the events of the movie, and the SGC program is reactivated and given a new objective - seek out and find the alien invaders and defeat them. Jack O''Neill is called out of retirement and sent to locate Daniel Jackson on Abydos.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/172562.jpg', '1997-07-27', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13438, 1, 2, 'The Enemy Within', 'While the U.S. government determines the fate of Teal''c, SGC must deal with one of its own that has been taken over by a Goa''uld.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/172597.jpg', '1997-08-01', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13439, 1, 3, 'Emancipation', 'SG-1 visits a planet settled by the ancient Mongols, where women are treated as second-class citizens.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/172602.jpg', '1997-08-08', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13440, 1, 4, 'The Broca Divide', 'SG-1 investigates a planet divided into a light and dark side, and ends up bringing back a plague that threatens to decimate SGC.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/172610.jpg', '1997-08-15', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13441, 1, 5, 'The First Commandment', 'SG-1 goes in search of the missing SG-9, but discovers that its leader has set himself up as a god on a planet of primitives.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/172617.jpg', '1997-08-22', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13442, 1, 6, 'Cold Lazarus', 'During an off-world assignment, Jack is struck down by energy from a blue crystal...which creates a duplicate of him that returns to Earth in Jack''s place.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/172625.jpg', '1997-08-29', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13443, 1, 7, 'The Nox', 'SG-1 travels to a planet with a creature that possesses the power of invisibility, but run afoul of Apophis and meet the mysterious Nox.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/172634.jpg', '1997-09-12', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13444, 1, 8, 'Brief Candle', 'After being greeted with open arms by the people of Argos, SG-1 discovers that not only do the Argosians suffer from rapid aging, but O''Neill has been somehow infected and will die in a few short days if they don''t find a cure.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/172644.jpg', '1997-09-19', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13445, 1, 9, 'Thor''s Hammer', 'Traveling to a planet quarantined by the Goa''uld, Jack and Teal''c are trapped in an underground labyrinth.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/172750.jpg', '1997-09-26', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13446, 1, 10, 'The Torment of Tantalus', 'Daniel discovers that there was a previous Stargate explorer - Dr. Ernest Littlefield, who went through the Gate in 1945. But he never returned, so SG-1 sets out to recover him.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/172815.jpg', '1997-10-03', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13447, 1, 11, 'Bloodlines', 'Teal''c reveals that he has a son who is due to receive a Goa''uld larva, and asks the team to help him save his child.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/172940.jpg', '1997-10-10', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13448, 1, 12, 'Fire and Water', 'After an expedition to the planet Oannes, Jack, Teal''c and Sam return...to reveal that Daniel died on the mission.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/172982.jpg', '1997-10-17', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13449, 1, 13, 'Hathor', 'The ancient Egyptian goddess and Goa''uld, Hathor, is awakened and immediately takes over SGC and all of its men.', 'https://static.tvmaze.com/uploads/images/medium_landscape/31/77559.jpg', '1997-10-24', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13450, 1, 14, 'Singularity', 'SG-1 rescues a little girl, Cassandra, but it soon turns out she is a pawn in a scheme to destroy Earth''s Stargate.', 'https://static.tvmaze.com/uploads/images/medium_landscape/31/77945.jpg', '1997-10-31', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13451, 1, 15, 'Cor-ai', 'Teal''c is put on trial by the inhabitants of a planet where he and the Goa''uld collected humans from the planet. If he is found guilty, he will be executed.', 'https://static.tvmaze.com/uploads/images/medium_landscape/31/77918.jpg', '1998-01-23', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13452, 1, 16, 'Enigma', 'SG-1 rescues a group of survivors from a dying planet, but finds that it must deal with its own people when military intelligence wants access to their advanced technology.', 'https://static.tvmaze.com/uploads/images/medium_landscape/31/79776.jpg', '1998-01-30', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13453, 1, 17, 'Solitudes', 'During a Stargate malfunction, Jack and Sam are redirected to an icy planet where they face a frozen death unless Stargate Command can determine their location.', 'https://static.tvmaze.com/uploads/images/medium_landscape/31/79785.jpg', '1998-02-06', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13454, 1, 18, 'Tin Man', 'SG-1 arrives on P3X-989 and is knocked unconscious - they wake up and return to Earth only to find that they are robots.', 'https://static.tvmaze.com/uploads/images/medium_landscape/31/79946.jpg', '1998-02-13', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13455, 1, 19, 'There But for the Grace of God', 'While investigating P3R-233, Daniel stumbles across a device that projects him into a parallel dimension. The parallel SGC (known as the SGA) must somehow dial out of their Stargate and get Daniel back to the planet so he can return to "his" universe.', 'https://static.tvmaze.com/uploads/images/medium_landscape/32/80870.jpg', '1998-02-20', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13456, 1, 20, 'Politics', 'The Stargate program faces an immediate threat - - from Senator Kinsey, a man who sees the program as wasteful. Even Daniel''s desperate warning of an imminent attack won''t sway the Senator, who is determined to bury the gate and put the program out of business.', 'https://static.tvmaze.com/uploads/images/medium_landscape/32/81049.jpg', '1998-02-27', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13457, 1, 21, 'Within the Serpent''s Grasp', 'With the Stargate being shut down, SG-1 decide to take one last trip through the ''gate to stop the Goa''uld attack that is imminent.', 'https://static.tvmaze.com/uploads/images/medium_landscape/32/81945.jpg', '1998-03-06', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13458, 2, 1, 'The Serpent''s Lair', 'With SG-1 trapped on Klorel''s ship, it seems that Earth is doomed as the pyramid ships prepare to destroy Earth.', 'https://static.tvmaze.com/uploads/images/medium_landscape/32/82458.jpg', '1998-06-26', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13459, 2, 2, 'In the Line of Duty', 'While on an off-world rescue mission, Sam becomes possessed by a Goa''uld symbiote.', 'https://static.tvmaze.com/uploads/images/medium_landscape/33/82975.jpg', '1998-07-03', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13460, 2, 3, 'Prisoners', 'After assisting a man that is a fleeing murderer, the team is sent through a Stargate to Hadante, a penal world where brute strength and raw power rule.', 'https://static.tvmaze.com/uploads/images/medium_landscape/33/82983.jpg', '1998-07-10', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13461, 2, 4, 'The Gamekeeper', 'SG-1 travel to P7J-989, where they discover a beautiful garden and a dome full of strange metallic chambers, each containing an unconscious person. As the team inspects the chambers, they are trapped and knocked unconscious.', 'https://static.tvmaze.com/uploads/images/medium_landscape/33/83655.jpg', '1998-07-17', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13462, 2, 5, 'Need', 'When Daniel is being manipulated by an alien princess, SG-1 is forced to labor in the mines.', 'https://static.tvmaze.com/uploads/images/medium_landscape/33/84130.jpg', '1998-07-24', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13463, 2, 6, 'Thor''s Chariot', 'SG-1 must return to Cimmeria in order to help fight off a Goa''uld invasion while searching for a mysterious hall put there by the Asgard Thor.', 'https://static.tvmaze.com/uploads/images/medium_landscape/34/85139.jpg', '1998-07-31', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13464, 2, 7, 'Message in a Bottle', 'While exploring a new planet, SG-1 find an orb that sends out electromagnetic signals. Thinking it''s a time capsule of some sort, they return to Earth to begin their tests; however, the object begins to heat up among other things.', 'https://static.tvmaze.com/uploads/images/medium_landscape/34/86108.jpg', '1998-08-07', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13465, 2, 8, 'Family', 'Bra''tac arrives with news that Teal''c''s son, Rya''c, has been kidnapped by Apophis. SG-1 must accompany Teal''c back to Chulak to rescue Rya''c.', 'https://static.tvmaze.com/uploads/images/medium_landscape/34/86110.jpg', '1998-08-14', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13466, 2, 9, 'Secrets', 'Jackson and Teal''c travel back to Abydos to fulfill a promise he made to Shau''re''s father Kasuf. When they arrive, Daniel learns that his wife, whom he hasn''t seen since she was taken by the Goa''uld, is nine months pregnant. The father is Apophis, who plans to use the baby as his new host.', 'https://static.tvmaze.com/uploads/images/medium_landscape/34/86112.jpg', '1998-08-21', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13467, 2, 10, 'Bane', 'While exploring planet BP6-3Q1, Teal''c is stung by a strange insect which causes him to become ill and almost die.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/174616.jpg', '1998-09-25', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13468, 2, 11, 'The Tok''ra', 'Through a dream, Captain Carter sees herself as Jolinar of Malkshur, running through a maze of blue walls and brightly coloured people. She stops at a DHD to dial an address. This, so she claims, is the Tok''ra base. So, SG-1 goes off the contact the Tok''ra. Meanwhile, Captain Carter''s father, Jacob, has cancer and it is getting worse.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/174637.jpg', '1998-10-02', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13469, 2, 12, 'The Tok''ra (Part Two)', 'The Tok''ra turns down a request for an alliance against the Goa''uld because Earth doesn''t offer enough rewards to justify the security breach. Selmak, a Tok''ra whose host is dying, requests a human host. Carter suggests her father, Jacob Carter, who is dying of cancer.', 'https://static.tvmaze.com/uploads/images/medium_landscape/69/174683.jpg', '1998-10-09', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13470, 2, 13, 'Spirits', 'SG-11 has not returned from its mission to PXY-887, where they recently discovered an element, trinium. After O''Neill becomes injured, Carter leads SG-1 through the Stargate to investigate and to negotiate a mining treaty with the inhabitants.', 'https://static.tvmaze.com/uploads/images/medium_landscape/70/175114.jpg', '1998-10-23', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13471, 2, 14, 'Touchstone', 'SG-1 discovers a device on a planet, Madrona, called the Touchstone which seems to have the ability to regulate the weather. SG-1 gets permission to stay on the planet to study the device but when they return it has been stolen and the Madronans blame SG-1.', 'https://static.tvmaze.com/uploads/images/medium_landscape/35/88546.jpg', '1998-10-30', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13472, 2, 15, 'The Fifth Race', 'While on the planet P3R-272, SG-1 comes across an ancient device that downloads a vast amount of knowledge into Jack''s brain. Jack has the task of helping Daniel solve ancient mysteries while trying to save himself from braindeath due to the overwhelming stress.', 'https://static.tvmaze.com/uploads/images/medium_landscape/71/177601.jpg', '1999-01-22', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13473, 2, 16, 'A Matter of Time', 'SG-10 is on a planet when its sun becomes a black hole, and the Stargate link back to Earth threatens to destroy first Stargate Command and then the entire planet.', 'https://static.tvmaze.com/uploads/images/medium_landscape/71/177696.jpg', '1999-01-29', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13474, 2, 17, 'Holiday', 'When the SG-1 team stumbles upon the chamber of former Goa''uld enemy Ma''chello, they fall victim to his powerful body-swapping invention. Ma''chello takes on Daniel''s body and the young archeologist finds himself trapped in the body of an old and dying man.', 'https://static.tvmaze.com/uploads/images/medium_landscape/71/177978.jpg', '1999-02-05', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13475, 2, 18, 'Serpent''s Song', 'Pursued by Goa''uld, Apophis throws himself on the mercy of SG-1. Despite his past evil, SG-1 grants him sanctuary. Apophis, who shows signs of having been tortured, is slowly dying and reveals that he is being pursued by an ancient and powerful Goa''uld named Sokar, the original god of death.', 'https://static.tvmaze.com/uploads/images/medium_landscape/71/177955.jpg', '1999-02-12', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13476, 2, 19, 'One False Step', 'During a routine reconnaissance mission, the UAV plane crashes into a cactus-like plant. Sent to recover the plane, SG-1 discovers that the inhabitants have begun falling ill, and before long a plague of illness sweeps the race.', 'https://static.tvmaze.com/uploads/images/medium_landscape/71/177992.jpg', '1999-02-19', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13477, 2, 20, 'Show and Tell', 'A young boy gains entry to the SGC and tells the SG-1 team he has come with his mother, a member of the invisible Reetou race. The boy announces that the Goa''uld destroyed his planet Reetalia and now Reetou rebels intend to kill all human beings to prevent possible future hosts.', 'https://static.tvmaze.com/uploads/images/medium_landscape/71/178022.jpg', '1999-02-26', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13478, 2, 21, '1969', 'SG-1 departs on what should be a routine mission and instead end up on Earth in 1969. They must find a way back home before it is too late.', 'https://static.tvmaze.com/uploads/images/medium_landscape/71/178285.jpg', '1999-03-05', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13479, 2, 22, 'Out of Mind', 'Awakening from cryogenic suspension, O''Neill finds himself in a futuristic version of the SGC. Doctors hook O''Neill to a device which turns his memories into holograms and then question him for information about races able to defeat the Goa''uld.', 'https://static.tvmaze.com/uploads/images/medium_landscape/71/178311.jpg', '1999-03-12', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13480, 3, 1, 'Into the Fire', 'General Hammond leads a daring rescue attempt with the help of Teal''c to retrieve SG-1. Meanwhile, on board the Goa''uld ship, one of the members of the team gets a present from Hathor... is it too late to save Colonel O''Neill?', 'https://static.tvmaze.com/uploads/images/medium_landscape/72/181569.jpg', '1999-06-25', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13481, 3, 2, 'Seth', 'The Tok''ra believe that the ancient Goa''uld System Lord, Seth, is hiding on Earth posing as a religious leader. SG-1 and the Tok''ra Selmak must find him without falling victim to his brainwashing powers.', 'https://static.tvmaze.com/uploads/images/medium_landscape/72/181581.jpg', '1999-07-02', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13482, 3, 3, 'Fair Game', 'The Asgard wish to include Earth in their protected planets treaty with the Goa''uld, which will save them from an attack. The negotiations are to take place at the SGC.', 'https://static.tvmaze.com/uploads/images/medium_landscape/38/95161.jpg', '1999-07-09', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13483, 3, 4, 'Legacy', 'Daniel starts going crazy after SG-1 visits a planet where SG-1 found nine dead Goa''uld. The doctors believe he is suffering from the effects of traveling through the gate.', 'https://static.tvmaze.com/uploads/images/medium_landscape/72/181616.jpg', '1999-07-16', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13484, 3, 5, 'Learning Curve', 'SG-1 visits a planet, Orban, where some children are the experts in their fields of knowledge. SG-1 finds this strange despite the Orbanians telling them it is normal; when they investigate some more, they find that all is not well on Orban.', 'https://static.tvmaze.com/uploads/images/medium_landscape/83/208685.jpg', '1999-07-23', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13485, 3, 6, 'Point of View', 'Alternate reality versions of Carter and Kawalsky use the quantum mirror to arrive at a secured building in the top secret Area 51 in "our" universe. When the alternate Carter begins to feel the effects of temporal distortion, SGC must come up with a plan to send the alternates back and help them defeat their Apophis.', 'https://static.tvmaze.com/uploads/images/medium_landscape/83/208703.jpg', '1999-07-30', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13486, 3, 7, 'Deadman Switch', 'The team are captured by a bounty hunter who plans to use them to capture a Goa''uld, but all is not as it seems.', 'https://static.tvmaze.com/uploads/images/medium_landscape/83/208713.jpg', '1999-08-06', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13487, 3, 8, 'Demons', 'SG-1 stumbles on a village that is about to sacrifice a young woman to the demon that plagues their village for being possessed. When the village leader discovers SG-1, their lives are threatened as he believes them also to be possessed, and they must fight for their lives.', 'https://static.tvmaze.com/uploads/images/medium_landscape/83/208719.jpg', '1999-08-13', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13488, 3, 9, 'Rules of Engagement', 'Upon exiting the Stargate, SG-1 finds itself in the midst of battle. A group of SG soldiers battle a Jaffa army. Believing the soldiers to be the missing-in-action SG-11 team, O''Neill and the others provide assistance. Much to their surprise, the mystery SG team turns their weapons on SG-1.', 'https://static.tvmaze.com/uploads/images/medium_landscape/83/208997.jpg', '1999-08-20', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13489, 3, 10, 'Forever in a Day', 'In the middle of a battlefield Daniel and Amonet meet in a tent. Amonet uses her hand device on Daniel, and when he awakes Amonet (and Sha''re) are dead, but when he returns to Earth, he keeps seeing her everywhere.', 'https://static.tvmaze.com/uploads/images/medium_landscape/83/209005.jpg', '1999-10-08', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13490, 3, 11, 'Past and Present', 'SG-1 travels to a planet whose inhabitants seem to be suffering from mass retrograde amnesia.', 'https://static.tvmaze.com/uploads/images/medium_landscape/83/209011.jpg', '1999-10-15', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13491, 3, 12, 'Jolinar''s Memories', 'The Tok''ra come to Earth and tell Sam that her dad has been captured and is being held prisoner by Sokar on a planet Earth people would describe as hell. Martouf informs them that Jolinar has escaped from this place once before, so it is up to Sam to remember how.', 'https://static.tvmaze.com/uploads/images/medium_landscape/83/209037.jpg', '1999-10-22', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13492, 3, 13, 'The Devil You Know', 'SG-1''s plan to escape has failed and Apophis has returned. They must find a new way off the planet before it is too late.', 'https://static.tvmaze.com/uploads/images/medium_landscape/83/209302.jpg', '1999-10-29', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13493, 3, 14, 'Foothold', 'When SG-1 returns from a mission, everyone at the SGC is acting strangely.', 'https://static.tvmaze.com/uploads/images/medium_landscape/83/209344.jpg', '1999-11-05', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13494, 3, 15, 'Pretense', 'The Tollan inform the SGC that Klor''el/Ska''ara have crash-landed on their planet and that they will hold a trial to determine which has the right to Ska''ara''s body. SG-1 is invited to Tollan to act as his defense.', 'https://static.tvmaze.com/uploads/images/medium_landscape/83/209394.jpg', '2000-01-21', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13495, 3, 16, 'Urgo', 'SG-1 travels to a paradisical-appearing planet... only to step immediately back out of the Stargate with no memory of their trip. They soon find themselves engaging in odd behavior, and find out that a computer chip has been planted in their minds during their memory blackout.', 'https://static.tvmaze.com/uploads/images/medium_landscape/83/209489.jpg', '2000-01-28', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13496, 3, 17, 'A Hundred Days', 'During an expedition to a civilized planet, the Stargate of that world is hit by a meteor, trapping O''Neill on that world without any apparent hope of rescue.', 'https://static.tvmaze.com/uploads/images/medium_landscape/84/210078.jpg', '2000-02-04', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13497, 3, 18, 'Shades of Grey', 'When the Tollan refuse to share technology, even after SG-1 saved the planet from a Goa''uld attack, Jack gets angry and steals a device from them. As a result, Jack is forced into early retirement.', 'https://static.tvmaze.com/uploads/images/medium_landscape/84/210099.jpg', '2000-02-11', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13498, 3, 19, 'New Ground', 'SG-1 discovers a planet on which two locals just discovered the Stargate that had been buried for thousands of years. Unfortunately, the authorities soon come and the military comes after the team, who think they are enemy spies and don''t believe a word they say.', 'https://static.tvmaze.com/uploads/images/medium_landscape/84/210144.jpg', '2000-02-18', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13499, 3, 20, 'Maternal Instinct', 'SG-1 journeys to Kheb to locate the Harcesis child.', 'https://static.tvmaze.com/uploads/images/medium_landscape/84/210171.jpg', '2000-02-25', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13500, 3, 21, 'Crystal Skull', 'While visiting a new world, the team discovers a skull fashioned from pink crystal, that Daniel cannot resist looking into - at which point he disappears. Unable to locate Dr Jackson, SG-1 return to Earth hoping to find a way to retrieve their lost friend.', 'https://static.tvmaze.com/uploads/images/medium_landscape/85/213544.jpg', '2000-03-03', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13501, 3, 22, 'Nemesis', 'The episode opens with Daniel Jackson confined to the infirmary recovering from an appendectomy. The rest of team is told to take a vacation, but before they can go, O''Neill is suddenly transported to Thor''s ship where he is informed that the enemy the Asgard deemed greater than the Goa''uld is onboard, and Thor needs Jack''s help to defeat them.', 'https://static.tvmaze.com/uploads/images/medium_landscape/85/213574.jpg', '2000-03-10', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13502, 4, 1, 'Small Victories', 'While Carter helps the Asgard fight the replicators galaxies away, Teal''c, Daniel, and O''Neill must contain them on Earth.', 'https://static.tvmaze.com/uploads/images/medium_landscape/85/213681.jpg', '2000-06-30', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13503, 4, 2, 'The Other Side', 'An alien race, the Eurondans, contact the SGC and ask for help. SG-1 delivers humanitarian aid to the aliens, who have been devastated by war by a hostile power, but must make a decision when Alar, the Eurondan''s representative, asks for military assistance against their enemy.', 'https://static.tvmaze.com/uploads/images/medium_landscape/85/213741.jpg', '2000-07-07', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13504, 4, 3, 'Upgrades', 'The Tok''ra ask the SG-1 to test some mysterious alien armbands, and they prove to confer vast super strength and speed on its wearers. SG-1 put their new-found "powers" to good use, but it soon becomes clear the armbands have a time limit that endanger the team in the midst of a critical mission.', 'https://static.tvmaze.com/uploads/images/medium_landscape/85/213788.jpg', '2000-07-14', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13505, 4, 4, 'Crossroads', 'Teal''c''s former love Shan''auc travels to Earth to ask for assistance - she has a way to tap into the memories of her symbiote and convince it that the Goa''uld are evil.', 'https://static.tvmaze.com/uploads/images/medium_landscape/85/213831.jpg', '2000-07-21', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13506, 4, 5, 'Divide and Conquer', 'During a meeting of the Tok''ra High Council, one of the SGC soldiers goes berserk and attacks them before taking his own life. It soon becomes clear that the Goa''uld have a new weapon - a mind control technique that can turn anyone into a preprogrammed assassin. SGC soon realizes that Jack and Sam may be the next programmed assassins.', 'https://static.tvmaze.com/uploads/images/medium_landscape/43/108441.jpg', '2000-07-28', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13507, 4, 6, 'Window of Opportunity', 'When an alien scientist activates a device that the Ancients created for time alterations, Jack and Teal''c get caught in a time loop.', 'https://static.tvmaze.com/uploads/images/medium_landscape/86/215416.jpg', '2000-08-04', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13508, 4, 7, 'Watergate', 'The Russians ask for assistance when they reveal they have the second Stargate, but it has become locked onto an alien water planet, not only preventing the SGC''s Gate from functioning but endangering the Russian base.', 'https://static.tvmaze.com/uploads/images/medium_landscape/86/215572.jpg', '2000-08-11', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13509, 4, 8, 'The First Ones', 'An archaeological team makes an amazing discovery - a planet holding primordial Goa''uld symbiotes. But the planet also is home to the Unas, the first race that acted as a host to the symbiote, and the team and SG-1 are soon in danger from the symbiotes.', 'https://static.tvmaze.com/uploads/images/medium_landscape/86/215591.jpg', '2000-08-18', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13510, 4, 9, 'Scorched Earth', 'SG-1 helps transfer the residents of a Goa''uld slave planet to a new world, but soon find the planet is the target of a terraforming effort that will wipe out its new inhabitants.', 'https://static.tvmaze.com/uploads/images/medium_landscape/86/216323.jpg', '2000-08-25', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13511, 4, 10, 'Beneath the Surface', 'SG-1 are brainwashed and given memories of new lives and put to work as mining slaves on an alien world. While Hammond tries to find out if they''re still alive, the SG-1 must struggle with their returning memories and plot their escape.', 'https://static.tvmaze.com/uploads/images/medium_landscape/86/216336.jpg', '2000-09-01', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13512, 4, 11, 'Point of No Return', 'Martin Lloyd, a conspiracy nutjob, calls up the SGC but has accurate knowledge of the Stargate. Martin claims to own a spaceship and is dismissed as a crackpot, but a series of incidents suggests that there may be more to his claims.', 'https://static.tvmaze.com/uploads/images/medium_landscape/86/216352.jpg', '2000-09-08', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13513, 4, 12, 'Tangent', 'A test of the X-301, an experimental aircraft adapted from two Goa''uld death gliders, goes awry sending O''Neill and Teal''c hurtling out of Earth''s orbit.', 'https://static.tvmaze.com/uploads/images/medium_landscape/86/216555.jpg', '2000-09-15', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13514, 4, 13, 'The Curse', 'When Daniel Jackson''s old archeology professor, Dr. Jordan, dies in a mysterious lab explosion, Daniel must return to visit his old academic stomping grounds.', 'https://static.tvmaze.com/uploads/images/medium_landscape/86/216585.jpg', '2000-09-22', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13515, 4, 14, 'The Serpent''s Venom', 'While visiting Chulak to gather support for a Jaffa rebellion, Teal''c is captured by the Goa''uld. The rest of SG-1, unaware of his fate, are dispatched by the Tok''ra to thwart a burgeoning alliance between Apophis and Heru-ur.', 'https://static.tvmaze.com/uploads/images/medium_landscape/86/216981.jpg', '2000-09-29', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13516, 4, 15, 'Chain Reaction', 'When General Hammond announces he is stepping down as head of the SGC, O''Neill suspects that there is more to his decision than he is letting on.', 'https://static.tvmaze.com/uploads/images/medium_landscape/86/217182.jpg', '2001-01-05', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13517, 4, 16, '2010', 'Nine years in the future, the Goa''uld have been defeated thanks to an alliance with an advanced alien race. However, Carter finds out that most of the human race has secretly been rendered sterile by Earth''s new allies.', 'https://static.tvmaze.com/uploads/images/medium_landscape/88/221965.jpg', '2001-01-12', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13518, 4, 17, 'Absolute Power', 'Daniel recovers Apophis''s son, the Harcesis. He has the memories of all the Goa''uld, which the SGC wants to obtain so that they can defeat their enemies. Daniel is given all the knowledge, but soon begins to use it in a tyrannical fashion.', 'https://static.tvmaze.com/uploads/images/medium_landscape/88/222042.jpg', '2001-01-19', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13519, 4, 18, 'The Light', 'A member of another SG team, returning from an alien planet, commits suicide. The rest of his team begins to go into comas, and Daniel, who also visited the planet, attempts suicide. SG-1 must determine the cause before it is too late.', 'https://static.tvmaze.com/uploads/images/medium_landscape/88/222057.jpg', '2001-01-26', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13520, 4, 19, 'Prodigy', 'During a visit to the Air Force Academy, Carter makes the acquaintance of Jennifer Hailey, a promising young cadet with great potential, but also a rebellious streak. Carter decides to show her what she can look forward to if she stays the course - by bringing her through the Stargate.', 'https://static.tvmaze.com/uploads/images/medium_landscape/89/224077.jpg', '2001-02-02', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13521, 4, 20, 'Entity', 'The SGC is infected by an alien probe that downloads itself into the base computers, accessing sensitive data on the SGC and its personnel.', 'https://static.tvmaze.com/uploads/images/medium_landscape/89/224189.jpg', '2001-02-09', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13522, 4, 21, 'Double Jeopardy', 'SG-1 returns to a planet they helped free from Goa''uld enslavement, but its people are not happy to see them. Instead they are angry that the Goa''uld came back when SG-1 told them they wouldn''t. Complicating matters, SG-1 doesn''t remember their previous visit.', 'https://static.tvmaze.com/uploads/images/medium_landscape/89/224205.jpg', '2001-02-16', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13523, 4, 22, 'Exodus', 'The SGC are loaning their Goa''uld Mothership to their good friends and allies, the Tok''ra, so they will be able to move to a planet that is not on the gate system. However, Tanith is caught out and tells Apophis where the Tok''ra are.', 'https://static.tvmaze.com/uploads/images/medium_landscape/89/224266.jpg', '2001-02-23', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13524, 5, 1, 'Enemies', 'SG-1 and Jacob Carter are trapped in another galaxy with Apophis, while Teal''c is brainwashed into believing that his defection from Apophis was all a ruse.', 'https://static.tvmaze.com/uploads/images/medium_landscape/90/226758.jpg', '2001-06-29', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13525, 5, 2, 'Threshold', 'Bra''tac must perform a Jaffa ritual bringing Teal''c to the brink of death to restore his true self.', 'https://static.tvmaze.com/uploads/images/medium_landscape/90/226780.jpg', '2001-07-06', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13526, 5, 3, 'Ascension', 'Carter finds romance from an alien who secretly followed her back from his planet.', 'https://static.tvmaze.com/uploads/images/medium_landscape/90/226790.jpg', '2001-07-13', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13527, 5, 4, 'The Fifth Man', 'O''Neill is stranded behind enemy lines fighting an unknown Goa''uld army. Teal''c, Carter, and Daniel return to the SGC but are faced with difficult questions from General Hammond when they report that a mysterious fifth member of SG-1 is trapped on the planet with Jack.', 'https://static.tvmaze.com/uploads/images/medium_landscape/90/226821.jpg', '2001-07-20', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13528, 5, 5, 'Red Sky', 'After a particularly rough ride through the Stargate, SG-1 arrives on a planet where the sky and the sun suddenly change to an orange-red color. The villagers immediately think it''s Ragnarok, but SG-1 soon discovers it''s a catastrophe of their own making.', 'https://static.tvmaze.com/uploads/images/medium_landscape/90/226839.jpg', '2001-07-27', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13529, 5, 6, 'Rite of Passage', 'Cassandra develops telekinetic powers which threatens to kill her. While seeking a cure, Dr. Fraiser uncovers a dark secret on Cassie''s home planet.', 'https://static.tvmaze.com/uploads/images/medium_landscape/90/226892.jpg', '2001-08-03', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13530, 5, 7, 'Beast of Burden', 'When Daniel''s friend Chaka is abducted by slave traders, SG-1 goes through the stargate to rescue him. However when the opportunity to free him comes, Chaka refuses to leave, and Daniel discovers Chaka has become the leader of the other Unas slaves.', 'https://static.tvmaze.com/uploads/images/medium_landscape/90/226916.jpg', '2001-08-10', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13531, 5, 8, 'The Tomb', 'SG-1 teams up with the Russians to find one of the latter''s missing teams, which were lost in a ziggurat on an alien planet.', 'https://static.tvmaze.com/uploads/images/medium_landscape/90/226935.jpg', '2001-08-17', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13532, 5, 9, 'Between Two Fires', 'Narim alerts SG-1 to possible dangers following the suspicious death of Omoc.', 'https://static.tvmaze.com/uploads/images/medium_landscape/90/227088.jpg', '2001-08-24', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13533, 5, 10, '2001', 'On an agrarian planet, SG-1 meets the Ashen Confederacy, who propose a trade accord with Earth.', 'https://static.tvmaze.com/uploads/images/medium_landscape/90/227101.jpg', '2001-08-31', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13534, 5, 11, 'Desperate Measures', 'When Carter goes missing, O''Neill teams up with Col. Maybourne again to free her from her unknown captors.', 'https://static.tvmaze.com/uploads/images/medium_landscape/90/227116.jpg', '2001-09-07', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13535, 5, 12, 'Wormhole X-Treme!', 'A space ship is approaching Earth and SGC knows it belongs to the aliens they met in the episode "Point of No Return." Martin, one of the aliens, wrote a television script to Hollywood about the SGC, and O''Neill has to join the filming crew to get closer to Martin and try to find more about the ship.', 'https://static.tvmaze.com/uploads/images/medium_landscape/90/227157.jpg', '2001-09-08', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13536, 5, 13, 'Proving Ground', 'The SGC embarks on a cadet training program.', 'https://static.tvmaze.com/uploads/images/medium_landscape/91/228300.jpg', '2002-03-08', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13537, 5, 14, '48 Hours', 'A Stargate mishap leaves Teal''c trapped inside the Stargate network, forcing the SGC to turn to the Russians for help.', 'https://static.tvmaze.com/uploads/images/medium_landscape/91/228314.jpg', '2002-03-15', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13538, 5, 15, 'Summit', 'When the System Lords call a summit to deal with a new threat against them, the Tok''ra and Daniel infiltrate the conference and plan to use a poison to wipe them out, but matters get complicated when Osiris, still in the body of Dr. Sarah Gardner, arrives.', 'https://static.tvmaze.com/uploads/images/medium_landscape/91/228321.jpg', '2002-03-22', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13539, 5, 16, 'Last Stand', 'Osiris is actually an emissary of Anubis and she petitions the System Lords to re-admit him. Meanwhile, Daniel in the guise of Lord Yu''s servant tries to save Sarah while Jacob waits cloaked nearby.', 'https://static.tvmaze.com/uploads/images/medium_landscape/91/228367.jpg', '2002-03-29', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13540, 5, 17, 'Fail Safe', 'Earth finds itself threatened when SG Command learns that an asteroid is on a collision course with the planet.', 'https://static.tvmaze.com/uploads/images/medium_landscape/93/233431.jpg', '2002-04-05', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13541, 5, 18, 'The Warrior', 'A charismatic new Jaffa leader seeks an alliance with the SGC and Earth.', 'https://static.tvmaze.com/uploads/images/medium_landscape/93/233481.jpg', '2002-04-12', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13542, 5, 19, 'Menace', 'SG-1 explores a planet and finds an inactive android, which when activated thinks it is a normal human girl.', 'https://static.tvmaze.com/uploads/images/medium_landscape/135/339504.jpg', '2002-04-26', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13543, 5, 20, 'The Sentinel', 'SG-1 finds a world under siege by Lord Svarog''s forces because the "Shades of Grey" NID team disabled the planet''s defenses. SG-1 must work with the captured team members to restore them.', 'https://static.tvmaze.com/uploads/images/medium_landscape/135/339533.jpg', '2002-05-03', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13544, 5, 21, 'Meridian', 'SG-1 returns from a planet with Daniel apparently dying from radiation poisoning.', 'https://static.tvmaze.com/uploads/images/medium_landscape/135/339558.jpg', '2002-05-10', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13545, 5, 22, 'Revelations', 'SG-1 attempts to rescue an Asgard scientist from the Goa''uld.', 'https://static.tvmaze.com/uploads/images/medium_landscape/135/339562.jpg', '2002-05-17', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13546, 6, 1, 'Redemption', 'The SGC has come under attack from Anubis, who has a device that can use one Stargate to destroy another. With a wormhole dialed in to Earth''s stargate, the SGC can not contact its off-world allies for help. Meanwhile Teal''c is off-world attending his wife''s funeral. Bra''tac and Teal''c search for the planet Anubis is attacking Earth from and prepare to go into battle against him.', 'https://static.tvmaze.com/uploads/images/medium_landscape/135/339729.jpg', '2002-06-07', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13547, 6, 2, 'Redemption Part 2', 'Rya''c insists that Teal''c allow him to join in battle, so he can see for himself what the war is all about. Together with Bra''tac, they deduce the planet Anubis is attacking Earth from, and set out to make a strike at his weapon. Meanwhile, on Earth, the efforts continue to find a way of preventing the destruction of the Stargate.', 'https://static.tvmaze.com/uploads/images/medium_landscape/135/339766.jpg', '2002-06-14', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13548, 6, 3, 'Descent', 'SG-1 is on a salvage mission for a Goa''uld mothership left behind by Anubis.', 'https://static.tvmaze.com/uploads/images/medium_landscape/135/339789.jpg', '2002-06-21', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13549, 6, 4, 'Frozen', 'The SGC''s study of the Antarctic Gate site reveals a woman buried in the ice.', 'https://static.tvmaze.com/uploads/images/medium_landscape/135/339803.jpg', '2002-06-28', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13550, 6, 5, 'Nightwalkers', 'Carter, Teal''c and Jonas investigate the death of a scientist with connections to the Goa''uld, and find a small town whose inhabitants are part of a secret experiment.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/340248.jpg', '2002-07-12', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13551, 6, 6, 'Abyss', 'Jack is captured by a Goa''uld named Ba''al after a mission led by his symbiote goes wrong. His only chance of redemption lies in the hands of Daniel.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/340267.jpg', '2002-07-19', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13552, 6, 7, 'Shadow Play', 'Jonas Quinn''s mentor visits him to tell that their people are about to use a deadly bomb in their nation''s war.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/340286.jpg', '2002-07-26', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13553, 6, 8, 'The Other Guys', 'While escorting physicists off-world, SG-1 is taken captive by a Goa''uld hoping to curry favor with Anubis. A pair of escaped physicists who revere SG-1 must rescue them.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/340467.jpg', '2002-08-02', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13554, 6, 9, 'Allegiance', 'There is an assassin at the SGC''s Alpha site, but is it a Jaffa or a Tok''ra?', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/340475.jpg', '2002-08-09', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13555, 6, 10, 'Cure', 'SG-1 is offered a deal for a miracle medicine from an alien world.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/340482.jpg', '2002-08-16', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13556, 6, 11, 'Prometheus', 'During a tour of the new X-303 (codenamed Prometheus), the ship is taken over by rogue NID agents.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/340751.jpg', '2002-08-23', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13557, 6, 12, 'Unnatural Selection', 'Using the Prometheus, SG-1 heads to a Replicator-controlled planet, where time moves faster due to Asgard technology. They hope to reverse the machine to freeze the Replicators in time.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/340772.jpg', '2003-01-10', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13558, 6, 13, 'Sight Unseen', 'After SG-1 returns to Earth with an Ancient device, incorporeal bug like creatures begin appearing in the SGC.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/341064.jpg', '2003-01-17', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13559, 6, 14, 'Smoke & Mirrors', 'Jack becomes the lead suspect in an assassination attempt on Senator Kinsey, and the rest of the team works to clear him.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/341084.jpg', '2003-01-24', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13560, 6, 15, 'Paradise Lost', 'Maybourne offers to reveal the location of an offworld weapon but only if he''s allowed to go. Once there, Maybourne tricks SG-1 and, along with Jack, is teleported to what he thinks is "utopia." However, the civilization that was once utopia is now dead.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/341100.jpg', '2003-01-31', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13561, 6, 16, 'Metamorphosis', 'SG-1 discovers that Nirrti has continued her experiments to create a hok''taur (perfect human).', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/341108.jpg', '2003-02-07', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13562, 6, 17, 'Disclosure', 'The existence of the Stargate is disclosed to other major countries.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/341227.jpg', '2003-02-14', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13563, 6, 18, 'Forsaken', 'Offworld, SG-1 discovers a crashed prison-transport ship, and find themselves caught between the guards and the prisoners.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/341320.jpg', '2003-02-21', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13564, 6, 19, 'The Changeling', 'Teal''c begins having dreams in which he and the rest of SG-1 are firemen, and he can''t decide which reality is real.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/341374.jpg', '2003-02-28', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13565, 6, 20, 'Memento', 'During a test flight of the Prometheus, the hyperdrive overloads, forcing SG-1 to go to a nearby planet to hopefully locate a Stargate. The only problem is that the gate has been buried in an unknown location.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/341380.jpg', '2003-03-07', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13566, 6, 21, 'Prophecy', 'On P4S-237, Jonas begins having visions of the future and Lord Mot destroying SG-1.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/341628.jpg', '2003-03-14', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13567, 6, 22, 'Full Circle', 'SG-1 must defend Abydos from Anubis, who has come to take the Eye of Ra, an object of fabled power.', 'https://static.tvmaze.com/uploads/images/medium_landscape/136/341644.jpg', '2003-03-21', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13568, 7, 1, 'Fallen', 'SG-1 searches a planet for the City of the Lost only to find Daniel, alive but without memory of his former life.', 'https://static.tvmaze.com/uploads/images/medium_landscape/137/342691.jpg', '2003-06-13', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13569, 7, 2, 'Homecoming', 'Sam and Jack travel to Kelowna to oppose Anubis.', 'https://static.tvmaze.com/uploads/images/medium_landscape/137/342880.jpg', '2003-06-13', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13570, 7, 3, 'Fragile Balance', 'SG-1 discovers that Jack has apparently regressed to the age of a teenager, and there is some mysterious connection to alien abductees and the Asgard.', 'https://static.tvmaze.com/uploads/images/medium_landscape/137/342892.jpg', '2003-06-20', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13571, 7, 4, 'Orpheus', 'eal''c''s son Rya''c and Bra''tac are prisoners at a Jaffa death camp. SG-1, however, will not let their friends meet a lethal end and are determined to rescue them.', 'https://static.tvmaze.com/uploads/images/medium_landscape/137/342906.jpg', '2003-06-27', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13572, 7, 5, 'Revisions', 'On a toxic planet, SG-1 finds a dome that protects its inhabitants, which are all linked to a computer, and one by one people begin disappearing without anyone else noticing.', 'https://static.tvmaze.com/uploads/images/medium_landscape/137/343110.jpg', '2003-07-11', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13573, 7, 6, 'Lifeboat', 'Daniel is possessed by the personalities of dozens of different individuals after boarding a ship holding bodies in suspended animation.', 'https://static.tvmaze.com/uploads/images/medium_landscape/137/343121.jpg', '2003-07-18', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13574, 7, 7, 'Enemy Mine', 'An abandoned Naquadah mine is found but the Unas on the planet refuse to surrender it because they consider it holy ground.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482560.jpg', '2003-07-25', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13575, 7, 8, 'Space Race', 'Carter joins an alien in a space race, but they soon learn that someone is sabotaging the ships.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482561.jpg', '2003-08-01', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13576, 7, 9, 'Avenger 2.0', 'Dr. Felger creates a virus that will disable other gates, but after a test run, the virus spreads, disabling the entire gate network.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482562.jpg', '2003-08-08', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13577, 7, 10, 'Birthright', 'SG-1 meets a group of female Jaffa who have rebelled against their System Lord, and due to the Jaffas'' short supply of symbiotes, SG-1 offers to give them Tretonin.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482566.jpg', '2003-08-15', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13578, 7, 11, 'Evolution', 'Daniel is taken hostage when he goes to South America in search of an alien device, while Carter and Teal''c investigate the appearance of a powerful new enemy.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482567.jpg', '2003-08-22', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13579, 7, 12, 'Evolution Part 2', 'Jack is sent to rescue Daniel, while Carter and Teal''c investigate the appearance of a powerful new enemy intent on wiping out the System Lords one by one.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482568.jpg', '2004-01-09', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13580, 7, 13, 'Grace', 'When Carter goes on a mission to retrieve the Prometheus, she awakens to find herself alone on the ship and starts experiencing strange things.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482569.jpg', '2004-01-16', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13581, 7, 14, 'Fallout', 'The SGC team is reunited with Jonas Quinn, who asks for their assistance as he''s discovered a naquadriah chain reaction threatens to destroy Kalowona.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482570.jpg', '2004-01-23', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13582, 7, 15, 'Chimera', 'Samantha Carter begins a relationship with a detective, from whom she must hide her life at Stargate Command. Daniel comes face to face with the Goa''uld who has taken his former girlfriend as a host.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482571.jpg', '2004-01-30', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13583, 7, 16, 'Death Knell', 'When Anubis''s Kull warriors attack the Alpha site, the self destruct is initiated, but not everyone is evacuated safely. Teal''c and Jack scour the surrounding area for Major Carter. Meanwhile, unrest amongst the allies increases as the possibility of a mole emerges.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482572.jpg', '2004-02-06', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13584, 7, 17, 'Heroes', 'A film crew comes to the SGC to document the normal functions of the SGC.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482573.jpg', '2004-02-13', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13585, 7, 18, 'Heroes Part 2', 'SGC is wracked by tragedy when one of their own is killed in a Goa''uld ambush.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482574.jpg', '2004-02-20', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13586, 7, 19, 'Resurrection', 'Sam, Teal''c, and Daniel head to a warehouse where they hope to find a rogue NID operation. Instead, they find a girl held prisoner there and a bigger mystery than they ever expected.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482575.jpg', '2004-02-27', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13587, 7, 20, 'Inauguration', 'The United States has a new President. Vice President (former Senator) Kinsey tries, once again, to take control of the Stargate Program, by persuading the new President that it is unsafe under Hammond''s command.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482576.jpg', '2004-03-05', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13588, 7, 21, 'Lost City', 'The SGC learns that Anubis is planning to attack Earth, so Jack once again downloads Ancient knowledge, hoping to find Ancient weapons capable of stopping the impending attack.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482577.jpg', '2004-03-12', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13589, 7, 22, 'Lost City Part 2', 'Using Jack''s Ancient knowledge, SG-1 goes to a planet in search of Ancient weapons but soon learn that the weapons are actually hidden on Earth. Will SG-1 be able to make it back in time before Anubis'' attack begins?', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482578.jpg', '2004-03-19', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13590, 8, 1, 'New Order', 'While Sam and Teal''c go to the planet of the former human-form Replicators to contact the Asgard to cure Jack, Daniel and Dr. Weir must deal with Goa''uld System Lords who want the Ancients weapon the Tau''ri used to destroy Anubis.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482579.jpg', '2004-07-09', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13591, 8, 2, 'New Order Part 2', 'As the Replicators overwhelm the new Asgard homeworld, SG-1 works to revive Jack, create an Ancients weapon to stop the invaders, and tries to find the missing Sam, who is held captive by the humanform Replicator Fifth in a virtual reality.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482580.jpg', '2004-07-09', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13592, 8, 3, 'Lockdown', 'A Russian Air Force Colonel comes to join SGC, as an alien creature shows up at the same time. The creature starts taking over members of the SGC. General O''Neill orders SGC to be locked down until the creature can be contained.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482581.jpg', '2004-07-23', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13593, 8, 4, 'Zero Hour', 'Five days in the life of SGC as Jack assumes full command of the base and has to deal with a rapidly growing alien plant, the capture of SG-1 by Ba''al, arguing alien delegates, and a tricky traitorous System Lord.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482582.jpg', '2004-07-30', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13594, 8, 5, 'Icon', 'Daniel attempts to aid a battle-ravaged society when the team''s appearance sparks a war.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482583.jpg', '2004-08-06', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13595, 8, 6, 'Avatar', 'The SGC experiment with a virtual reality chair from the Gamekeeper''s world (season 2), but Teal''c becomes trapped in a virtual loop against an undefeatable batch of Anubis drones.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482584.jpg', '2004-08-13', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13596, 8, 7, 'Affinity', 'Teal''c moves into an apartment off-base where he becomes involved in a neighbor''s problems. Meanwhile, Carter''s boyfriend, Peter Shanahan, proposes and Carter tries to decide. Teal''c is then charged for murder and kidnapping and Daniel disappears while trying to prove Teal''c innocent.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482585.jpg', '2004-08-20', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13597, 8, 8, 'Covenant', 'A rich industrialist has evidence to prove that there is alien life on other planets and gives the governments of the world 24 hours to reveal the truth or he''s revealing it. The Air Force must decide how to handle the situation.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482586.jpg', '2004-08-27', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13598, 8, 9, 'Sacrifices', 'Teal''c is upset when his son Rya''c plans to marry a Jaffa woman of the Haktyl who he sees as not fit for him. Meanwhile, the Haktyl have been compromised, and Ishta is forced to move her people into the SGC until they find a suitable planet to move to.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482587.jpg', '2004-09-10', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13599, 8, 10, 'Endgame', 'The Trust is behind a plan to steal the Stargate and eliminate the Jaffa and the Goa''uld with the Tok''ra poison.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482588.jpg', '2004-09-17', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13600, 8, 11, 'Gemini', 'The Replicator Carter that Fifth created contacts the SGC and tells them that she wants to be destroyed. She also tells them that Fifth has made all Replicators immune to the disruptor. But does she have an ulterior motive...?', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482589.jpg', '2005-01-21', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13601, 8, 12, 'Prometheus Unbound', 'A Kull warrior manages to ring aboard the Proetheus on its way to Atlantis. It rings all of the crew off the ship except for Daniel, who must deal with the Kull warrior when he is left alone on the ship with it.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482590.jpg', '2005-01-28', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13602, 8, 13, 'It''s Good To Be King', 'The planet that Harry Maybourne was relocated to by the Tok''ra is targeted by a System Lord and SG-1 must go to rescue him. They discover that Harry has made himself king using knowledge of the Ancients--knowledge that may give them access to the Ancients'' time-travel technology.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482591.jpg', '2005-02-04', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13603, 8, 14, 'Full Alert', 'Robert Kinsey contacts General O''Neill and tells him that the Trust is trying to bring down the U.S. government, and want Kinsey''s help. Kinsey and the Trust escape surveillance but when the trail leads to Russia, Daniel is captured when it is revealed that Kinsey tried to kill a leading Russian general.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482592.jpg', '2005-02-11', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13604, 8, 15, 'Citizen Joe', 'Jack is confronted in his home by an irate barber who claims to know everything about the Stargate project and SG-1.', 'https://static.tvmaze.com/uploads/images/medium_landscape/120/300546.jpg', '2005-02-18', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13605, 8, 16, 'Reckoning', 'The Replicators threaten to overwhelm the galaxy, taking out the Goa''uld and then Earth. While Sam and Thor work to develop a weapon, Teal''c and Bra''tac lead the rebel Jaffa in taking a major temple and Jack and Jacob are forced to make an alliance with Ba''al.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482593.jpg', '2005-02-25', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13606, 8, 17, 'Reckoning Part 2', 'Ba''al sends his fleet back to retake the planet Dakara, pitting his ships against Teal''c and the Jaffa. The RepliCarter tries to probe Daniel''s mind to find all the Ancients'' knowledge, while Jacob and Carter discover the Ancient weapon on Dakara and try to figure out how to use it to destroy the Replicators.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482594.jpg', '2005-03-04', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13607, 8, 18, 'Threads', 'While Daniel finds himself in a mysterious diner suspended between death and ascension, Jacob''s fate takes an unexpected turn, Jack and Sam consider their romantic lives, and Anubis unleashes his plan for galactic destruction.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482595.jpg', '2005-03-11', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13608, 8, 19, 'Moebius', 'SG-1 and General O''Neill use the time traveling puddlejumper to go to Ancient Egypt to recover a ZPM. They successfully steal it, but something is wrong and the future is altered to that the Stargate program never happened. Daniel, Sam, and Jack must find a way to save their reality despite never having met before.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482596.jpg', '2005-03-18', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13609, 8, 20, 'Moebius Part 2', 'The alternate SG-1 must go back to ancient Egypt to correct the past. They meet the original timeline Daniel who is the only survivor of a failed rebellion against Ra. Together, they must formulate a plan to steal the Stargate so that Ra cannot take it with him.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482597.jpg', '2005-03-25', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13610, 9, 1, 'Avalon', 'Lt. Colonel Cameron Mitchell comes to the SGC to be the newest member of SG-1, but he soon learns from General Hank Landry, O''Neill''s successor, that the team has disbanded. However, when Vala arrives on Earth with a tablet that supposedly tells the location of an Ancient treasure, Daniel cannot help but be intrigued.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482598.jpg', '2005-07-15', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13611, 9, 2, 'Avalon Part 2', 'Daniel Jackson and Vala are seemingly transported into the bodies of two people in a distant galaxy on a planet populated by worshippers of a strange authority.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482600.jpg', '2005-07-22', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13612, 9, 3, 'Origin', 'Stargate Command encounters missionaries for a race of "gods" known as the Ori, who have zero tolerance for disbelievers.', 'https://static.tvmaze.com/uploads/images/medium_landscape/66/165301.jpg', '2005-07-29', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13613, 9, 4, 'The Ties That Bind', 'In order to free themselves of the bond created by the Kor mak bracelets, Daniel and Vala must locate and return the items she stole from the bracelets'' previous owner.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482601.jpg', '2005-08-05', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13614, 9, 5, 'The Powers That Be', 'SG-1 and Vala go to a planet where she is still worshipped as Qetesh, and in order to prove to the people that the Ori aren''t truly gods, she tells them the truth about herself. However, she is then forced to stand trial and possibly be executed.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482602.jpg', '2005-08-12', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13615, 9, 6, 'Beachhead', 'When the Ori create a force field around a free Jaffa planet, General Landry orders Carter to use a weapon that she designed against the Ori''s forces.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482603.jpg', '2005-08-19', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13616, 9, 7, 'Ex Deus Machina', 'A System Lord is found hiding on Earth, and he threatens to activate a naquadah bomb hidden somewhere in the United States if the SGC tries to go after him.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482604.jpg', '2005-08-26', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13617, 9, 8, 'Babylon', 'Offworld, SG-1 is attacked by Jaffa of the Sodan, and Mitchell is wounded in a fight with one of them. Thinking that the Jaffa was killed, the other Jaffa take Mitchell back to their village to be trained for a fight to the death.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482605.jpg', '2005-09-09', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13618, 9, 9, 'Prototype', 'SG-1 finds a Goa''uld-Human hybrid in stasis in an abandoned Goa''uld lab and take it back to Earth to study, where they learn it was created using Anubis'' DNA.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482606.jpg', '2005-09-16', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13619, 9, 10, 'The Fourth Horseman', 'After an SGC officer returns to Earth after unknowingly being infected with the Ancient Plague, the virus quickly spreads throughout the United States. Not wanting the Ori to gain control of the Milky Way Galaxy, Orlin yet again descends to help Carter find a cure.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482607.jpg', '2005-09-16', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13620, 9, 11, 'The Fourth Horseman Part 2', 'Members of the SGC start to become infected while Mitchell and Daniel try to capture the Prior.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482608.jpg', '2006-01-06', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13621, 9, 12, 'Collateral Damage', 'When SG-1 travels to an Asgard protected planet, Colonel Mitchell is accused of a murder he did not commit--but has memories showing he did.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482609.jpg', '2006-01-13', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13622, 9, 13, 'Ripple Effect', 'Alternate realities coming together at Stargate Command create alternate versions of SG-1 and some of their fallen allies.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482610.jpg', '2006-01-20', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13623, 9, 14, 'Stronghold', 'Ba''al kidnaps and brainwashes members of the Jaffa High Council in a bid to seize control of the Jaffa. Meanwhile, Mitchell debates whether to reveal the Stargate program to a dying friend who was once in line for his SG-1 position.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482611.jpg', '2006-01-27', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13624, 9, 15, 'Ethon', 'SG-1 and the Prometheus travel to Tegalus to stop the Rand Protectorate from using an Ori-supplied superweapon to destroy their enemies, the Caledonians. But things turn grim when Daniel is captured and the Prometheus is caught in a firefight.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482612.jpg', '2006-02-03', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13625, 9, 16, 'Off the Grid', 'The SGC learns that the organization of traders and mercenaries known as the Lucian Alliance is distributing a highly-addictive drug and SG-1 goes to investigate. But the situation becomes complicated when the planet''s Stargate disappears, and SG-1 is held responsible.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482614.jpg', '2006-02-10', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13626, 9, 17, 'The Scourge', 'While a group of foreign delegates are touring the Gamma Site, a swarm of alien bugs linked to the Ori escapes containment and adapt to become carnivorous.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482615.jpg', '2006-02-17', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13627, 9, 18, 'Arthur''s Mantle', 'Carter and Mitchell find themselves trapped on another plane, out of phase and invisible to everyone else. While Sam attempts to reverse the procedure, Mitchell goes after an assassin who is wiping out the Sodan.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482616.jpg', '2006-02-24', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13628, 9, 19, 'Crusade', 'Using an Ancient communication device, Vala contacts the SGC through Daniel and informs them of what''s been happening in the Ori''s galaxy.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482617.jpg', '2006-03-03', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13629, 9, 20, 'Camelot', 'The team learns of an ancient weapons system in the village of Camelot on an alien planet.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482618.jpg', '2006-03-10', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13630, 10, 1, 'Flesh and Blood', 'As the Ori gain power with their invasion of Chulak, Vala''s daughter Adria ages years in a matter of hours and the secret of her conception is revealed.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482619.jpg', '2006-07-14', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13631, 10, 2, 'Morpheus', 'The team goes off-world seeking a weapon against the Ori and ends up in serious trouble. Meanwhile, Landry is faced with having to decide whether or not Vala can be trusted to remain at the SGC.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482620.jpg', '2006-07-21', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13632, 10, 3, 'The Pegasus Project', 'Daniel and Vala travel to Atlantis in search of Merlin''s anti-Ori weapon, while Sam and Mitchell join forces with Dr. McKay to lock out the Ori supergate.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482621.jpg', '2006-07-28', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13633, 10, 4, 'Insiders', 'Stargate Command faces off against their old nemesis Ba''al and his clones as Landry spars with the NID and Agent Barrett.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482622.jpg', '2006-08-04', 1);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13634, 10, 5, 'Uninvited', 'While assisting SG-3 on an offworld mission, Teal''c encounters a savage alien creature that is killing the inhabitants. SG-1 investigates and learns that a parasite is to blame. The team suspects that the Ori are responsible, but they are shocked when they find out the real cause.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482623.jpg', '2006-08-11', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13635, 10, 6, '200', 'Mitchell eagerly awaits the next off-world mission, which will be his 200th trip through the Stargate. However, Martin Lloyd returns and seeks help with his movie script. The Pentagon (and General Jack O''Neill specifically) orders SG-1 to assist, much to SG-1''s chagrin.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482624.jpg', '2006-08-18', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13636, 10, 7, 'Counterstrike', 'After Adria''s followers on a planet are wiped out, she attempts to learn the location of this powerful new weapon.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482625.jpg', '2006-08-25', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13637, 10, 8, 'Memento Mori', 'Vala finds herself alone in a city with no memory of her identity or past life. Meanwhile, Mitchell and Teal''c question a man named Weaver who may have information about Vala''s whereabouts.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482626.jpg', '2006-09-08', 2);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13638, 10, 9, 'Company of Thieves', 'Mitchell attempts to infiltrate the Lucian Alliance in order to rescue members of the SG-1 team from the fallout of an Alliance civil war.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482627.jpg', '2006-09-15', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13639, 10, 10, 'The Quest', 'The SG-1 team continues their quest for the Holy Grail, an Ancient device capable of killing the ascended Ori. They learn that an old nemesis is also looking for the device.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482631.jpg', '2006-09-22', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13640, 10, 11, 'The Quest Part 2', 'SG-1, Adria, and Ba''al must defeat the dragon and continue their quest to search for Merlin''s weapon.', 'https://static.tvmaze.com/uploads/images/medium_landscape/71/178380.jpg', '2007-04-13', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13641, 10, 12, 'Line in the Sand', 'Mitchell, Carter and Teal''c arrive on a planet being threatened by the Ori. They decide that a line needs to be drawn and that the Ori must not be allowed to advance any further. Carter attempts to use the Ancient Merlin''s technology to prevent the Ori from taking over the planet.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482632.jpg', '2007-04-20', 3);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13642, 10, 13, 'The Road Not Taken', 'Carter ends up in an alternate universe and changes the course of things in that universe.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482633.jpg', '2007-04-27', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13643, 10, 14, 'The Shroud', 'The SG-1 team learns of yet another world that has been visited by a Prior of the Ori. However, this Prior hasn''t issued any threats. The team waits for the Prior''s return, only to be shocked by his identity.', 'https://static.tvmaze.com/uploads/images/medium_landscape/71/179075.jpg', '2007-05-04', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13644, 10, 15, 'Bounty', 'Col. Mitchell returns to Kansas to attend his high school reunion with Vala when Stargate Command learns of an attack on SG-1 team members.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482634.jpg', '2007-05-11', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13645, 10, 16, 'Bad Guys', 'SG-1 finds an alien museum on another planet but are mistaken for a bunch of rebels that have taken hostages.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482635.jpg', '2007-05-18', 4);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13646, 10, 17, 'Talion', 'After a terrorist attack on a Jaffa summit leaves many dead and Bra''tac seriously injured, Teal''c goes on a one-man quest for revenge.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482636.jpg', '2007-06-01', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13647, 10, 18, 'Family Ties', 'Vala''s father Jacek contacts SGC claiming to have vital information that could impact the survival of Earth. Meanwhile, Gen. Landry''s ex-wife pays a visit.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482637.jpg', '2007-06-08', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13648, 10, 19, 'Dominion', 'SG-1 gets caught in the middle when Ba''al and Adria compete for domination of the galaxy.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482638.jpg', '2007-06-15', 5);
INSERT INTO episodes (id, season, number, title, summary, image, airdate, disc) VALUES (13649, 10, 20, 'Unending', 'The SG-1 team extends a small time frame to several years to survive an attack of the Ori and tries to find a solution to solve their problem.', 'https://static.tvmaze.com/uploads/images/medium_landscape/193/482639.jpg', '2007-06-22', 5);
